var payload = msg.payload;

if (typeof payload === "string") {
    try {
        payload = JSON.parse(payload);
    } catch (e) {
        return null;
    }
}

// Convert to numbers explicitly
var x = parseFloat(payload.x);
var y = parseFloat(payload.y);
var magnitude = parseFloat(payload.magnitude);

// Validation: drop message (return null) if X or Y fall outside bounds [0, 255] or are invalid
if (isNaN(x) || isNaN(y) || x < 0 || x > 255 || y < 0 || y > 255) {
    return null;
}

// Add measurement name for InfluxDB with proper number types
msg.payload = [
    {
        measurement: "joystick",
        fields: {
            x: x,
            y: y,
            magnitude: magnitude
        },
        tags: {
            source: "simulator"
        },
        timestamp: new Date()
    }
];
return msg;

var payload = msg.payload;

// Convert to number explicitly
var pressed_count = parseInt(payload, 10);
if (isNaN(pressed_count) && typeof payload === "object") {
    pressed_count = parseInt(payload.pressed_count, 10);
}

// Validation: pressed_count cannot be negative
if (pressed_count < 0 || isNaN(pressed_count)) {
    return null;
}

// Add measurement name for InfluxDB with proper number type
msg.payload = [
    {
        measurement: "buttons",
        fields: {
            pressed_count: pressed_count
        },
        tags: {
            source: "simulator"
        },
        timestamp: new Date()
    }
];
return msg;
